entries[343410] = { ["name"] = "Hammer des Schmieds", ["text"] = "100 Meter Reichweite\nSofort\nRuft die Magie der Wissenschaft herbei, um Euren Hammer zu ermächtigen: Phaestus, Genesis der Äonen, gesegnetes Instrument der Ersten Schmiedin, Medium der Erschaffung des ersten Zenturios und der Spitzen des Aufstiegs. Erschafft ein Feld ungebundener Anima, das 30 Sek. lang Gegnern innerhalb von 10 Metern alle 3 Sek. 5 Arkanschaden zufügt." }
