entries[343415] = { ["name"] = "Entfesseln", ["text"] = "Sofort\nBeschwört eine mächtige Erinnerung und entfesselt ihre Macht, was 15 Arkanschaden verursacht und einen Bereich aufwallender Emotionen hinterlässt. Gegner in diesem Bereich erleiden im Verlauf von 10 Sek. 50 Arkanschaden." }
