entries[343418] = { ["name"] = "Arkane Kugel", ["text"] = "300 Meter Reichweite\nWirken in 2 sek.\nErzeugt eine Kugel aus instabiler arkaner Energie, die explodiert, wenn sie nicht von einem Spielercharakter absorbiert wird. Während der Spielercharakter in der Kugel steht, absorbiert er die instabilen Energien, erleidet dabei aber Arkanschaden.\nWenn ein Spielercharakter lange genug in der Kugel steht, wird diese vollständig absorbiert." }
entries[343419] = { ["name"] = "Arkane Kugel", ["text"] = "300 Meter Reichweite\nSofort\nErzeugt eine Kugel aus instabiler arkaner Energie, die explodiert, wenn sie nicht von einem Spielercharakter absorbiert wird. Während der Spielercharakter in der Kugel steht, absorbiert er die instabilen Energien, erleidet dabei aber Arkanschaden.\nWenn ein Spielercharakter lange genug in der Kugel steht, wird diese vollständig absorbiert." }
